36	    @Mapping(target = "bulkSignupWarning", ignore = true)
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
41	     * last names, as required by the API's read-only {@code displayName} field.
42	     *
43	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
44	     * applied only where referenced via {@code qualifiedByName}.
45	     */
46	    @Named("formatDisplayName")
47	    default String formatDisplayName(Owner owner) {
48	        if (owner == null) {
49	            return null;
50	        }
51	        return owner.getLastName() + ", " + owner.getFirstName();
52	    }
53	
54	    /**
55	     * Formats an owner's initials as the upper-cased first letters of the first and last
56	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
57	     * API's read-only {@code initials} field.
58	     *
