64	        if (owner == null) {
65	            return null;
66	        }
67	        return initial(owner.getFirstName()) + initial(owner.getLastName());
68	    }
69	
70	    /**
71	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
72	     * {@code customerCode} is the owner's {@code '<REGION>-<HASH8>'} customer code and
73	     * {@code YY} is the last two digits of the registration date's year (e.g.
74	     * {@code 'NSW-1A2B3C4D-M26'}), as required by the API's read-only
75	     * {@code membershipNumber} field. Returns {@code null} when either the customer code
76	     * or registration date is absent.
77	     *
78	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
79	     * applied only where referenced via {@code qualifiedByName}.
80	     */
81	    @Named("formatMembershipNumber")
82	    default String formatMembershipNumber(Owner owner) {
83	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
84	            return null;
85	        }
86	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
87	    }
88	
89	    /**
90	     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
91	     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
92	     * code. Returns {@code null} when the customer code is absent.
93	     *
94	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
95	     * applied only where referenced via {@code qualifiedByName}.
96	     */
97	    @Named("formatCheckDigit")
98	    default Integer formatCheckDigit(Owner owner) {
99	        if (owner == null || owner.getCustomerCode() == null) {
100	            return null;
101	        }
102	        return LuhnCheckDigit.compute(owner.getCustomerCode());
103	    }
104	
105	    /**
106	     * Derives an owner's membership level, as required by the API's read-only
107	     * {@code membershipLevel} field: starting at 1, plus 1 when an email address is present,
108	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), capped at 3. (Level 4
109	     * is reserved for tenure.)
110	     *
111	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
112	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
113	     * to record the membership level on the create audit line).
114	     */
115	    @Named("formatMembershipLevel")
116	    default Integer formatMembershipLevel(Owner owner) {
117	        if (owner == null) {
118	            return null;
119	        }
120	        int level = 1;
121	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
122	            level++;
123	        }
124	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
